const {capture}=require('./workspaces/extractor-srs-design/runtime/capture-and-parse.js');
const {tablesFromHtml,LIMITS}=require('./workspaces/extractor-srs-design/runtime/html-response-parser.js');
const url='https://chatgpt.com/share/6ae9dd85-7ff0-83e8-90c3-4592305a2362';
(async()=>{
  const c=await capture(url);
  const t=tablesFromHtml(c.html.toString('utf8'),LIMITS);
  const stats=t.tables.map((table,i)=>{
    const promises=table.map((v,index)=>({v,index})).filter(o=>Array.isArray(o.v)&&o.v[0]==='P');
    return {table:i,slots:table.length,promiseCount:promises.length,promiseValueTypes:Object.fromEntries([...new Set(promises.map(o=>typeof o.v[1]))].map(type=>[type,promises.filter(o=>typeof o.v[1]===type).length])),firstPromiseSlots:promises.slice(0,8).map(o=>({index:o.index,tagLength:o.v.length,valueType:typeof o.v[1]}))};
  });
  console.log(JSON.stringify({http_status:c.http_status,html_bytes:c.html.length,matching_calls:t.matchingCalls,stats}));
})().catch(e=>{console.log(JSON.stringify({error:e.code||e.name,message:e.message}));process.exitCode=1});
